1	import { scan, type Token } from "./scan";
2	
3	export type AstNode =
4	  | { type: "term"; value: string; phrase?: boolean; wildcard?: boolean }
5	  | { type: "and"; left: AstNode; right: AstNode }
6	  | { type: "or"; left: AstNode; right: AstNode }
7	  | { type: "and_not"; left: AstNode; right: AstNode };
8	
9	export type ParseError = {
10	  code: string;
11	  message: string;
12	  position: number;
13	};
14	
15	export type ParseResult =
16	  | { ok: true; ast: AstNode | null; leafCount: number; wildcardCount: number }
17	  | { ok: false; error: ParseError };
18	
19	const MAX_CHARS = 500;
20	const MAX_DEPTH = 8;
21	const MAX_LEAVES = 20;
22	const MAX_WILDCARDS = 5;
23	const MIN_PREFIX = 2;
24	
25	class Parser {
26	  tokens: Token[];
27	  i = 0;
28	  leafCount = 0;
29	  wildcardCount = 0;
30	  depth = 0;
31	
32	  constructor(tokens: Token[]) {
33	    this.tokens = tokens;
34	  }
35	
36	  peek(): Token {
37	    return this.tokens[this.i] ?? { kind: "EOF", value: "", start: 0, end: 0 };
38	  }
39	
40	  take(): Token {
41	    const t = this.peek();
42	    this.i++;
43	    return t;
44	  }
45	
46	  parse(): ParseResult {
47	    if (this.peek().kind === "EOF") {
48	      return { ok: true, ast: null, leafCount: 0, wildcardCount: 0 };
49	    }
50	    try {
51	      const ast = this.parseOr();
52	      if (this.peek().kind !== "EOF") {
53	        return {
54	          ok: false,
55	          error: {
56	            code: "unexpected_token",
57	            message: `Unexpected token (position ${this.peek().start})`,
58	            position: this.peek().start,
59	          },
60	        };
61	      }
62	      return {
63	        ok: true,
64	        ast,
65	        leafCount: this.leafCount,
66	        wildcardCount: this.wildcardCount,
67	      };
68	    } catch (e) {
69	      const err = e as ParseError;
70	      return { ok: false, error: err };
71	    }
72	  }
73	
74	  fail(code: string, message: string, position: number): never {
75	    throw { code, message, position } satisfies ParseError;
76	  }
77	
78	  parseOr(): AstNode {
79	    let left = this.parseAnd();
80	    while (this.peek().kind === "OR") {
81	      this.take();
82	      if (this.peek().kind === "EOF" || this.peek().kind === "RPAREN") {
83	        this.fail("dangling_or", `OR needs a term on both sides (position ${this.peek().start})`, this.peek().start);
84	      }
85	      const right = this.parseAnd();
86	      left = { type: "or", left, right };
87	    }
88	    return left;
89	  }
90	
91	  parseAnd(): AstNode {
92	    let left = this.parseUnary();
93	    for (;;) {
94	      const t = this.peek();
95	      if (t.kind === "AND") {
96	        this.take();
97	        if (this.peek().kind === "NOT") {
98	          this.take();
99	          const right = this.parseUnary();
100	          left = { type: "and_not", left, right };
101	          continue;
102	        }
103	        if (
104	          this.peek().kind === "EOF" ||
105	          this.peek().kind === "RPAREN" ||
106	          this.peek().kind === "OR" ||
107	          this.peek().kind === "AND"
108	        ) {
109	          this.fail(
110	            "dangling_and",
111	            `AND needs a term on both sides (position ${t.end})`,
112	            t.end,
113	          );
114	        }
115	        const right = this.parseUnary();
116	        left = { type: "and", left, right };
117	        continue;
118	      }
119	      if (
120	        t.kind === "WORD" ||
121	        t.kind === "PHRASE" ||
122	        t.kind === "WILDCARD" ||
123	        t.kind === "LPAREN"
124	      ) {
125	        // implicit AND
126	        const right = this.parseUnary();
127	        left = { type: "and", left, right };
128	        continue;
129	      }
130	      break;
131	    }
132	    return left;
133	  }
134	
135	  parseUnary(): AstNode {
136	    const t = this.peek();
137	    if (t.kind === "NOT") {
138	      this.fail("bare_not", "Use AND NOT to exclude a term", t.start);
139	    }
140	    if (t.kind === "AND" || t.kind === "OR") {
141	      this.fail(
142	        "dangling_op",
143	        `${t.value} needs a term on both sides (position ${t.start})`,
144	        t.start,
145	      );
146	    }
147	    if (t.kind === "LPAREN") {
148	      this.take();
149	      this.depth++;
150	      if (this.depth > MAX_DEPTH) {
151	        this.fail("depth", "Query nests too deeply", t.start);
152	      }
153	      if (this.peek().kind === "RPAREN") {
154	        this.fail("empty_group", "Empty group", t.start);
155	      }
156	      const inner = this.parseOr();
157	      if (this.peek().kind !== "RPAREN") {
158	        this.fail("unbalanced", `Missing closing bracket (position ${this.peek().start})`, this.peek().start);
159	      }
160	      this.take();
161	      this.depth--;
162	      return inner;
163	    }
164	    if (t.kind === "PHRASE") {
165	      this.take();
166	      if (!t.value.trim()) this.fail("empty_phrase", "Empty phrase", t.start);
167	      this.leafCount++;
168	      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
169	      return { type: "term", value: t.value, phrase: true };
170	    }
171	    if (t.kind === "WILDCARD") {
172	      this.take();
173	      if (t.value.length < MIN_PREFIX) {
174	        this.fail("short_prefix", "Wildcard prefix must be at least 2 characters", t.start);
175	      }
176	      if (/[*]/.test(t.value) || t.value.includes("*")) {
177	        this.fail("bad_wildcard", "Wildcards go at the end of a single word", t.start);
178	      }
179	      this.leafCount++;
180	      this.wildcardCount++;
181	      if (this.wildcardCount > MAX_WILDCARDS) this.fail("wildcards", "Too many wildcards", t.start);
182	      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
183	      return { type: "term", value: t.value, wildcard: true };
184	    }
185	    if (t.kind === "WORD") {
186	      this.take();
187	      this.leafCount++;
188	      if (this.leafCount > MAX_LEAVES) this.fail("leaves", "Too many terms", t.start);
189	      return { type: "term", value: t.value };
190	    }
191	    this.fail("unexpected", `Unexpected token (position ${t.start})`, t.start);
192	  }
193	}
194	
195	export function parseQuery(input: string): ParseResult {
196	  if (input.length > MAX_CHARS) {
197	    return {
198	      ok: false,
199	      error: {
200	        code: "too_long",
201	        message: `Query exceeds ${MAX_CHARS} characters`,
202	        position: 0,
203	      },
204	    };
205	  }
206	  const trimmed = input.trim();
207	  if (!trimmed) {
208	    return { ok: true, ast: null, leafCount: 0, wildcardCount: 0 };
209	  }
210	  const tokens = scan(input);
211	  // Detect unclosed quote: scan leaves PHRASE without closing — check raw
212	  if ((input.match(/"/g) ?? []).length % 2 === 1) {
213	    const pos = input.lastIndexOf('"');
214	    return {
215	      ok: false,
216	      error: { code: "unclosed_phrase", message: "Unclosed phrase", position: pos },
217	    };
218	  }
219	  // Reject mid-word wildcards like a*b
220	  for (const t of tokens) {
221	    if (t.kind === "WORD" && t.value.includes("*")) {
222	      return {
223	        ok: false,
224	        error: {
225	          code: "bad_wildcard",
226	          message: "Wildcards go at the end of a single word",
227	          position: t.start,
228	        },
229	      };
230	    }
231	  }
232	  return new Parser(tokens).parse();
233	}
234

