1	export type TokenKind =
2	  | "LPAREN"
3	  | "RPAREN"
4	  | "AND"
5	  | "OR"
6	  | "NOT"
7	  | "WORD"
8	  | "PHRASE"
9	  | "WILDCARD"
10	  | "EOF";
11	
12	export type Token = {
13	  kind: TokenKind;
14	  value: string;
15	  start: number;
16	  end: number;
17	};
18	
19	/** Hand-written character-loop scanner (no regex). */
20	export function scan(input: string): Token[] {
21	  const tokens: Token[] = [];
22	  let i = 0;
23	  const n = input.length;
24	
25	  const isSpace = (c: string) => c === " " || c === "\t" || c === "\n" || c === "\r";
26	
27	  while (i < n) {
28	    const c = input[i]!;
29	    if (isSpace(c)) {
30	      i++;
31	      continue;
32	    }
33	    if (c === "(") {
34	      tokens.push({ kind: "LPAREN", value: "(", start: i, end: i + 1 });
35	      i++;
36	      continue;
37	    }
38	    if (c === ")") {
39	      tokens.push({ kind: "RPAREN", value: ")", start: i, end: i + 1 });
40	      i++;
41	      continue;
42	    }
43	    if (c === '"') {
44	      const start = i;
45	      i++;
46	      let value = "";
47	      while (i < n && input[i] !== '"') {
48	        value += input[i];
49	        i++;
50	      }
51	      if (i >= n) {
52	        tokens.push({ kind: "PHRASE", value, start, end: i });
53	        break;
54	      }
55	      i++; // closing quote
56	      tokens.push({ kind: "PHRASE", value, start, end: i });
57	      continue;
58	    }
59	
60	    const start = i;
61	    let value = "";
62	    while (i < n) {
63	      const ch = input[i]!;
64	      if (isSpace(ch) || ch === "(" || ch === ")" || ch === '"') break;
65	      value += ch;
66	      i++;
67	    }
68	
69	    if (value === "AND") {
70	      tokens.push({ kind: "AND", value, start, end: i });
71	    } else if (value === "OR") {
72	      tokens.push({ kind: "OR", value, start, end: i });
73	    } else if (value === "NOT") {
74	      tokens.push({ kind: "NOT", value, start, end: i });
75	    } else if (value.endsWith("*") && value.length > 1) {
76	      tokens.push({ kind: "WILDCARD", value: value.slice(0, -1), start, end: i });
77	    } else if (value === "*") {
78	      tokens.push({ kind: "WILDCARD", value: "", start, end: i });
79	    } else {
80	      tokens.push({ kind: "WORD", value, start, end: i });
81	    }
82	  }
83	
84	  tokens.push({ kind: "EOF", value: "", start: n, end: n });
85	  return tokens;
86	}
