1	import { counter } from "../metrics";
2	import type { AstNode } from "./parse";
3	import {
4	  classifyLeaf,
5	  escapeIlike,
6	  EXPR,
7	  isEnglishStopword,
8	  normaliseLeafTerm,
9	} from "./leaf";
