11	const emptyStem = counter(
12	  "mss_search_empty_stem_total",
13	  "Stop-word wildcards that omitted the English stem half",
14	);
15	
16	export type CompiledQuery = {
17	  sql: string | null;
18	  params: unknown[];
19	  /** Original-side-only predicate (same param indices as sql). */
20	  originalSql: string | null;
21	  /** Translation-side EXISTS predicate (same param indices as sql). */
22	  translationSql: string | null;
23	  /** Summary-side EXISTS predicate (same param indices as sql). */
24	  summarySql: string | null;
25	  /** Broadest term kind in the query for telemetry (ADR-0036). */
26	  broadestKind: "exact" | "wildcard" | "nonlatin_sub" | "none";
27	};
28	
29	type Side = "both" | "original" | "translation" | "summary";
30	
31	type TermMeta = {
32	  key: string;
33	  value: unknown;
34	  kind: ReturnType<typeof classifyLeaf>;
35	  /** When stem is empty (stop-word wildcard), omit the stem half. */
36	  stemEmpty: boolean;
37	  /** Sanitised stem text for wildcard english half (plainto_tsquery). */
38	  stemValue?: string;
39	};
40	
41	/**
42	 * Compile AST to a SQL boolean fragment.
43	 * Positive term leaves match original OR current translation OR current summary (ADR-0035).
44	 * Bare/quoted Latin terms are exact on the simple vector; `term*` is prefix OR English stem (ADR-0036).
45	 * The right side of `and_not` matches the original only (ADR-0027).
46	 */
47	export function compileAst(ast: AstNode | null, startIndex = 1): CompiledQuery {
48	  if (!ast) {
49	    return {
50	      sql: null,
51	      params: [],
52	      originalSql: null,
53	      translationSql: null,
54	      summarySql: null,
55	      broadestKind: "none",
56	    };
57	  }
58	
59	  const params: unknown[] = [];
60	  let next = startIndex;
61	  const indexByKey = new Map<string, number>();
62	  const metaByNode = new WeakMap<object, TermMeta>();
63	  let broadestKind: CompiledQuery["broadestKind"] = "exact";
64	
65	  function widenKind(k: TermMeta["kind"]) {
66	    if (k === "substring") {
67	      broadestKind = "nonlatin_sub";
68	      return;
69	    }
70	    if (k === "wildcard") {
71	      if (broadestKind !== "nonlatin_sub") broadestKind = "wildcard";
72	      return;
73	    }
74	    // exact / phrase stay at exact unless already wider
75	  }
76	
77	  function paramIndex(key: string, value: unknown): number {
78	    const existing = indexByKey.get(key);
79	    if (existing !== undefined) return existing;
80	    params.push(value);
81	    const i = next;
82	    next++;
83	    indexByKey.set(key, i);
84	    return i;
85	  }
86	
87	  function termMeta(node: Extract<AstNode, { type: "term" }>): TermMeta {
88	    const cached = metaByNode.get(node);
89	    if (cached) return cached;
90	
91	    const classifyOpts: { phrase?: boolean; wildcard?: boolean } = {};
92	    if (node.phrase) classifyOpts.phrase = true;
93	    if (node.wildcard) classifyOpts.wildcard = true;
94	    const kind = classifyLeaf(node.value, classifyOpts);
95	    const norm = normaliseLeafTerm(node.value);
96	    const stemEmpty = kind === "wildcard" && isEnglishStopword(norm);
97	    if (stemEmpty) emptyStem.inc();
98	    widenKind(kind);
99	
100	    let meta: TermMeta;
101	    if (kind === "substring") {
102	      meta = { key: `sub:${norm}`, value: `%${escapeIlike(norm)}%`, kind, stemEmpty };
103	    } else if (kind === "phrase") {
104	      meta = { key: `phrase:${norm}`, value: norm, kind, stemEmpty };
105	    } else if (kind === "wildcard") {
106	      const safe = norm.replace(/[^\p{L}\p{N}]+/gu, "");
107	      meta = {
108	        key: `wild:${safe}`,
109	        value: `${safe}:*`,
110	        kind,
111	        stemEmpty,
112	        stemValue: safe,
113	      };
114	    } else {
115	      meta = { key: `exact:${norm}`, value: norm, kind, stemEmpty };
116	    }
117	    metaByNode.set(node, meta);
118	    return meta;
119	  }
120	
121	  function translationExists(predicate: string): string {
122	    return `EXISTS (SELECT 1 FROM article_translations t
123	      WHERE t.article_id = a.id
124	        AND t.article_version = a.version
125	        AND t.superseded_at IS NULL
126	        AND (${predicate}))`;
127	  }
128	
129	  function summaryExists(predicate: string): string {
130	    return `EXISTS (SELECT 1 FROM derived_values dv
131	      WHERE dv.article_id = a.id
132	        AND dv.field = 'summary'
133	        AND dv.is_current
134	        AND (${predicate}))`;
135	  }
136	
137	  function origStem(idx: number): string {
138	    return `(${EXPR.articlesLangPred} AND ${EXPR.articlesFtsEn} @@ plainto_tsquery('english', $${idx}))`;
139	  }
140	
141	  function origSub(idx: number): string {
142	    return `a.search_text ILIKE $${idx} ESCAPE '\\'`;
143	  }
144	
145	  function origExact(idx: number): string {
146	    return `a.search_vector @@ plainto_tsquery('simple', $${idx})`;
147	  }
148	
149	  function origPhrase(idx: number): string {
150	    return `a.search_vector @@ phraseto_tsquery('simple', $${idx})`;
151	  }
152	
153	  function origWild(idx: number): string {
154	    return `a.search_vector @@ to_tsquery('simple', $${idx})`;
155	  }
156	
157	  function trStem(idx: number): string {
158	    return `${EXPR.translationsFtsEn} @@ plainto_tsquery('english', $${idx})`;
159	  }
160	
161	  function trSub(idx: number): string {
162	    return `t.search_text ILIKE $${idx} ESCAPE '\\'`;
163	  }
164	
165	  function trExact(idx: number): string {
166	    return `t.search_vector @@ plainto_tsquery('simple', $${idx})`;
167	  }
168	
169	  function trPhrase(idx: number): string {
170	    return `t.search_vector @@ phraseto_tsquery('simple', $${idx})`;
171	  }
172	
173	  function trWild(idx: number): string {
174	    return `t.search_vector @@ to_tsquery('simple', $${idx})`;
175	  }
176	
177	  function sumStem(idx: number): string {
178	    return `${EXPR.summaryFtsEn} @@ plainto_tsquery('english', $${idx})`;
179	  }
180	
181	  function sumSub(idx: number): string {
182	    return `dv.value ILIKE $${idx} ESCAPE '\\'`;
183	  }
184	
185	  function sumExact(idx: number): string {
186	    return `${EXPR.summarySimple} @@ plainto_tsquery('simple', $${idx})`;
187	  }
188	
189	  function sumPhrase(idx: number): string {
190	    return `${EXPR.summarySimple} @@ phraseto_tsquery('simple', $${idx})`;
191	  }
192	
193	  function sumWild(idx: number): string {
194	    return `${EXPR.summarySimple} @@ to_tsquery('simple', $${idx})`;
195	  }
196	
197	  function compileWildcard(meta: TermMeta, side: Side): string {
198	    const prefixIdx = paramIndex(meta.key, meta.value);
199	
200	    if (meta.stemEmpty) {
201	      // Prefix only — do not bind an unused stem param (FP-S7).
202	      if (side === "original") return origWild(prefixIdx);
203	      if (side === "translation") return translationExists(trWild(prefixIdx));
204	      if (side === "summary") return summaryExists(sumWild(prefixIdx));
205	      return `(${origWild(prefixIdx)} OR ${translationExists(trWild(prefixIdx))} OR ${summaryExists(sumWild(prefixIdx))})`;
206	    }
207	
208	    const stemIdx = paramIndex(`stem_of:${meta.key}`, meta.stemValue ?? meta.value);
209	    const orig = `(${origWild(prefixIdx)} OR ${origStem(stemIdx)})`;
210	    const tr = `(${trWild(prefixIdx)} OR ${trStem(stemIdx)})`;
211	    const sum = `(${sumWild(prefixIdx)} OR ${sumStem(stemIdx)})`;
212	
213	    if (side === "original") return orig;
214	    if (side === "translation") return translationExists(tr);
215	    if (side === "summary") return summaryExists(sum);
216	    return `(${orig} OR ${translationExists(tr)} OR ${summaryExists(sum)})`;
217	  }
218	
219	  function compileTerm(node: Extract<AstNode, { type: "term" }>, side: Side): string {
220	    const meta = termMeta(node);
221	
222	    if (meta.kind === "substring") {
223	      const idx = paramIndex(meta.key, meta.value);
224	      if (side === "original") return origSub(idx);
225	      if (side === "translation") return translationExists(trSub(idx));
226	      if (side === "summary") return summaryExists(sumSub(idx));
227	      return `(${origSub(idx)} OR ${translationExists(trSub(idx))} OR ${summaryExists(sumSub(idx))})`;
228	    }
229	
230	    if (meta.kind === "phrase") {
231	      const idx = paramIndex(meta.key, meta.value);
232	      if (side === "original") return origPhrase(idx);
233	      if (side === "translation") return translationExists(trPhrase(idx));
234	      if (side === "summary") return summaryExists(sumPhrase(idx));
235	      return `(${origPhrase(idx)} OR ${translationExists(trPhrase(idx))} OR ${summaryExists(sumPhrase(idx))})`;
236	    }
237	
238	    if (meta.kind === "wildcard") {
239	      return compileWildcard(meta, side);
240	    }
241	
242	    // exact (bare or quoted single word)
243	    const idx = paramIndex(meta.key, meta.value);
244	    if (side === "original") return origExact(idx);
245	    if (side === "translation") return translationExists(trExact(idx));
246	    if (side === "summary") return summaryExists(sumExact(idx));
247	    return `(${origExact(idx)} OR ${translationExists(trExact(idx))} OR ${summaryExists(sumExact(idx))})`;
248	  }
249	
250	  function compile(node: AstNode, side: Side): string {
251	    switch (node.type) {
252	      case "and":
253	        return `(${compile(node.left, side)}) AND (${compile(node.right, side)})`;
254	      case "or":
255	        return `(${compile(node.left, side)}) OR (${compile(node.right, side)})`;
256	      case "and_not":
257	        // NOT never uses translation or summary (ADR-0027, ADR-0035)
258	        if (side === "translation" || side === "summary") return compile(node.left, side);
259	        if (side === "original") {
260	          return `(${compile(node.left, "original")}) AND NOT (${compile(node.right, "original")})`;
261	        }
262	        return `(${compile(node.left, "both")}) AND NOT (${compile(node.right, "original")})`;
263	      case "term":
264	        return compileTerm(node, side);
265	    }
266	  }
267	
268	  // Register params by walking "both" first (visits every term once in order).
269	  const sql = compile(ast, "both");
270	  const originalSql = compile(ast, "original");
271	  const translationSql = compile(ast, "translation");
272	  const summarySql = compile(ast, "summary");
273	
274	  return { sql, params, originalSql, translationSql, summarySql, broadestKind };
275	}
