2	
3	/** Match modes for a single term leaf (ADR-0031, 0035, 0036). */
4	export type LeafKind =
5	  | "exact"
6	  | "substring"
7	  | "phrase"
8	  | "wildcard";
9	
10	/** Postgres `english` stop words that yield an empty plainto_tsquery. */
11	const ENGLISH_STOPWORDS = new Set([
12	  "a",
13	  "about",
14	  "an",
15	  "are",
16	  "as",
17	  "at",
18	  "be",
19	  "but",
20	  "by",
21	  "for",
22	  "from",
23	  "has",
24	  "he",
25	  "in",
26	  "is",
27	  "it",
28	  "its",
29	  "of",
30	  "on",
31	  "that",
32	  "the",
33	  "to",
34	  "was",
35	  "were",
36	  "will",
37	  "with",
38	]);
39	
40	export function isEnglishStopword(term: string): boolean {
41	  return ENGLISH_STOPWORDS.has(term.toLocaleLowerCase("en-US"));
42	}
43	
44	/**
45	 * True when the term has any letter that is not Latin-script.
46	 * Digits and punctuation alone do not force substring; Cyrillic/Greek/Hebrew/etc. do.
47	 */
48	export function termHasNonLatinLetter(term: string): boolean {
49	  // Any letter whose script is not Latin → substring path (ADR-0007 / review 0005).
50	  return /\p{L}/u.test(term) && /[^\p{Script=Latin}\p{N}\p{P}\p{Z}\p{M}]/u.test(term);
51	}
52	
53	/**
54	 * Choose match mode by script, quoting, wildcard (ADR-0036).
55	 * Bare Latin terms are exact; stemming applies only to `term*`.
56	 * Quoted single-word phrases are exact; multi-word phrases stay phrase.
57	 */
58	export function classifyLeaf(term: string, opts?: { phrase?: boolean; wildcard?: boolean }): LeafKind {
59	  if (opts?.wildcard) return "wildcard";
60	  if (opts?.phrase) {
61	    if (/\s/.test(term.trim())) return "phrase";
62	    return "exact";
63	  }
64	  if (termHasNonLatinLetter(term)) return "substring";
65	  return "exact";
66	}
67	
68	export function escapeIlike(term: string): string {
69	  return term.replace(/\\/g, "\\\\").replace(/%/g, "\\%").replace(/_/g, "\\_");
70	}
71	
72	export function normaliseLeafTerm(term: string): string {
73	  return normaliseText(term);
74	}
75	
76	/** Exact expression text must match migration 0007 (FP-DB1). */
77	export const EXPR = {
78	  articlesFtsEn: `to_tsvector('english', a.search_text)`,
79	  articlesLangPred: `split_part(a.language, '-', 1) IN ('en', 'und')`,
80	  translationsFtsEn: `to_tsvector('english', t.search_text)`,
81	  summaryFtsEn: `to_tsvector('english', dv.value)`,
82	  summarySimple: `to_tsvector('simple', dv.value)`,
83	} as const;
