219	      ingested_at: r.ingested_at,
220	      version: Number(r.version ?? 1),
221	      headline_en: (r.headline_en as string | null) ?? null,
222	      matched_in: matchedIn,
223	      derived: hydrate.derivedBy.get(String(r.id)) ?? [],
224	      jobs: hydrate.jobsBy.get(String(r.id)) ?? [],
225	    };
226	  });
227	
228	  let nextCursor: string | null = null;
229	  if (hasMore) {
230	    const last = page[page.length - 1]!;
231	    nextCursor = encodeCursor(
232	      {
233	        publishedAt: new Date(last.published_at as string).toISOString(),
234	        id: String(last.id),
235	        filterHash,
236	      },
237	      config.cursorSecret,
238	    );
239	  }
240	
241	  let coverage: SearchCoverage | null = null;
242	  let translationCoverage: TranslationCoverage | null = null;
243	  let summaryMissing = 0;
244	  let trgmIndex = true;
245	  const echoNotes: string[] = [];
246	
247	  if (corpusSignals && filteredCov) {
248	    coverage = {
249	      articles_matching_base_filters: filteredCov.articles_matching_base_filters,
250	      articles_in_scope: filteredCov.articles_in_scope,
251	      corpus_articles: corpusSignals.corpus_articles,
252	      enriched_sentiment: corpusSignals.enriched_sentiment,
253	      enriched_topics: corpusSignals.enriched_topics,
254	      excluded_by_filter_not_enriched: filteredCov.excluded_by_filter_not_enriched,
255	      watermark: corpusSignals.watermark,
256	    };
257	    translationCoverage = filteredCov.translation;
258	    summaryMissing = filteredCov.summary_missing;
259	    trgmIndex = corpusSignals.trgm_index;
260	  } else {
261	    echoNotes.push("Coverage figures are temporarily unavailable.");
262	    if (corpusSignals) trgmIndex = corpusSignals.trgm_index;
263	  }
264	
265	  let total: number | undefined;
266	  if (sp.includeTotal) {
267	    const countParams = [...compiled.params, ...afterText.params];
268	    const countWhere = whereParts.length ? `WHERE ${whereParts.join(" AND ")}` : "WHERE true";
269	    const c = await db.query<{ n: string }>(
270	      `SELECT count(*)::text AS n FROM articles a ${countWhere}`,
271	      countParams,
272	    );
273	    total = Number(c.rows[0]?.n ?? 0);
274	  }
275	
276	  if (termHasNonLatinLetter(q)) {
277	    echoNotes.push(
278	      "Non-Latin terms are matched as text fragments in the original and in the translation.",
279	    );
280	  }
281	  if (/\bNOT\b/.test(q)) {
282	    echoNotes.push("NOT terms exclude articles by their original text only.");
283	  }
284	  if (!trgmIndex && hasNonLatinTerm(parsed.ast)) {
285	    echoNotes.push("Partial-word matching is running slowly right now.");
286	  }
287	  if (summaryMissing > 0) {
288	    echoNotes.push(
289	      `${summaryMissing} articles in this selection have no summary yet, so English terms in summaries may miss them.`,
290	    );
291	  }
292	
293	  return {
294	    status: 200 as const,
295	    body: {
296	      articles,
297	      next_cursor: nextCursor,
298	      parsed: echoAst(parsed.ast),
299	      echo_notes: echoNotes,
300	      coverage,
301	      translation_coverage: translationCoverage,
302	      summary_missing: summaryMissing,
303	      trgm_index: trgmIndex,
304	      search_kind: compiled.broadestKind,
305	      ...(total !== undefined ? { total } : {}),
306	      resolved_range: {
307	        from: filters.from?.toISOString() ?? null,
308	        to: filters.to?.toISOString() ?? null,
309	      },
310	    },
311	    timing: queryMs,
312	  };
313	}
314	
315	function hasNonLatinTerm(ast: import("./parse").AstNode | null): boolean {
316	  if (!ast) return false;
317	  if (ast.type === "term") {
318	    const opts: { phrase?: boolean; wildcard?: boolean } = {};
319	    if (ast.phrase) opts.phrase = true;
320	    if (ast.wildcard) opts.wildcard = true;
321	    return classifyLeaf(ast.value, opts) === "substring";
322	  }
323	  if (ast.type === "and" || ast.type === "or" || ast.type === "and_not") {
324	    return hasNonLatinTerm(ast.left) || hasNonLatinTerm(ast.right);
325	  }
326	  return false;
327	}
328	
329	/** True when the query has a bare Latin term and no wildcard (UX zero-result hint). */
330	export function hasBareLatinNoWildcard(ast: import("./parse").AstNode | null): boolean {
331	  if (!ast) return false;
332	  let bareLatin = false;
333	  let hasWildcard = false;
334	  function walk(node: import("./parse").AstNode) {
335	    if (node.type === "term") {
336	      if (node.wildcard) hasWildcard = true;
337	      else if (!node.phrase && classifyLeaf(node.value) === "exact") bareLatin = true;
338	      return;
339	    }
340	    walk(node.left);
341	    walk(node.right);
342	  }
343	  walk(ast);
344	  return bareLatin && !hasWildcard;
345	}
346	
347	async function hydratePage(
348	  db: pg.Pool | pg.PoolClient,
349	  ids: string[],
350	): Promise<{
351	  derivedBy: Map<string, pg.QueryResultRow[]>;
352	  jobsBy: Map<string, pg.QueryResultRow[]>;
353	}> {
354	  const derivedBy = new Map<string, pg.QueryResultRow[]>();
355	  const jobsBy = new Map<string, pg.QueryResultRow[]>();
356	  if (ids.length === 0) return { derivedBy, jobsBy };
357	
358	  const res = await db.query<{ kind: string; payload: pg.QueryResultRow }>(
359	    `SELECT 'derived' AS kind, to_jsonb(d.*) AS payload
360	       FROM derived_values d
361	      WHERE d.article_id = ANY($1::bigint[]) AND d.is_current
362	     UNION ALL
363	     SELECT 'job' AS kind, to_jsonb(j.*) AS payload
364	       FROM enrichment_jobs j
365	      WHERE j.article_id = ANY($1::bigint[])`,
366	    [ids],
367	  );
368	  for (const r of res.rows) {
369	    const row = r.payload;
370	    const k = String(row.article_id);
371	    if (r.kind === "derived") {
372	      const list = derivedBy.get(k) ?? [];
373	      list.push(row);
374	      derivedBy.set(k, list);
375	    } else {
376	      const list = jobsBy.get(k) ?? [];
377	      list.push(row);
378	      jobsBy.set(k, list);
379	    }
380	  }
381	  return { derivedBy, jobsBy };
382	}
383	
384	type CorpusSignals = {
385	  corpus_articles: number;
386	  enriched_sentiment: number;
387	  enriched_topics: number;
388	  watermark: { published_at: string | null; ingested_at: string | null };
389	  trgm_index: boolean;
390	};
391	
392	async function readCorpusSignals(db: pg.Pool | pg.PoolClient): Promise<CorpusSignals | null> {
393	  try {
394	    const res = await db.query<{ key: string; value: string }>(
395	      `SELECT key, value FROM system_flags WHERE key = ANY($1::text[])`,
396	      [COVERAGE_FLAG_KEYS],
397	    );
398	    const map = new Map(res.rows.map((r) => [r.key, r.value]));
399	    // Cold start: worker has not written coverage flags yet — treat as unavailable.
400	    if (!map.has("coverage_corpus_articles")) return null;
401	    const pub = map.get("coverage_watermark_published_at") ?? "";
402	    const ing = map.get("coverage_watermark_ingested_at") ?? "";
403	    return {
404	      corpus_articles: Number(map.get("coverage_corpus_articles") ?? 0),
405	      enriched_sentiment: Number(map.get("coverage_enriched_sentiment") ?? 0),
406	      enriched_topics: Number(map.get("coverage_enriched_topics") ?? 0),
407	      watermark: {
408	        published_at: pub.length ? pub : null,
409	        ingested_at: ing.length ? ing : null,
410	      },
411	      trgm_index: map.get("trgm_index") === "on",
412	    };
413	  } catch {
414	    return null;
415	  }
416	}
417	
418	type FilteredCoverage = {
419	  articles_matching_base_filters: number;
420	  articles_in_scope: number;
421	  excluded_by_filter_not_enriched: number;
422	  summary_missing: number;
423	  translation: TranslationCoverage;
424	};
425	
426	async function computeFilteredCoverage(
427	  db: pg.Pool | pg.PoolClient,
428	  filters: SearchFilters,
429	): Promise<FilteredCoverage | null> {
430	  try {
431	    const base = baseFiltersOnly(filters);
432	    const baseBuild = buildFilterClauses(base, 1);
433	    const fullBuild = buildFilterClauses(filters, baseBuild.nextIndex);
434	    const baseWhere = baseBuild.clauses.length
435	      ? `WHERE ${baseBuild.clauses.join(" AND ")}`
436	      : "WHERE true";
437	    const fullWhere = fullBuild.clauses.length
438	      ? `WHERE ${fullBuild.clauses.join(" AND ")}`
439	      : "WHERE true";
440	    const params = [...baseBuild.params, ...fullBuild.params];
441	
442	    const derivedFilterActive = Boolean(
443	      (filters.sentiments && filters.sentiments.some((s) => s !== "not_enriched")) ||
444	        (filters.topics && filters.topics.some((t) => t !== "not_enriched")),
445	    );
446	
447	    const res = await db.query<{
448	      base_count: string;
449	      sel_count: string;
450	      summary_missing: string;
451	      foreign: string;
452	      translated: string;
453	      queued: string;
454	      paused: string;
455	      failed: string;
456	      older_not_scheduled: string;
457	    }>(
458	      `WITH base AS (
459	         SELECT a.id, a.version, a.language
460	           FROM articles a
461	           ${baseWhere}
462	       ),
463	       sel AS (
464	         SELECT a.id, a.version, a.language
465	           FROM articles a
466	           ${fullWhere}
467	       ),
468	       foreign_sel AS (
469	         SELECT s.* FROM sel s
470	          WHERE lower(split_part(replace(coalesce(s.language,''), '_', '-'), '-', 1))
471	                NOT IN ('en', 'eng')
472	             OR coalesce(trim(s.language), '') = ''
473	       )
474	       SELECT
475	         (SELECT count(*)::text FROM base) AS base_count,
476	         (SELECT count(*)::text FROM sel) AS sel_count,
477	         (SELECT count(*)::text FROM sel s
478	           WHERE NOT EXISTS (
479	             SELECT 1 FROM derived_values dv
480	              WHERE dv.article_id = s.id AND dv.field = 'summary' AND dv.is_current
481	           )) AS summary_missing,
482	         (SELECT count(*)::text FROM foreign_sel) AS foreign,
483	         (SELECT count(*)::text FROM foreign_sel f
484	           JOIN article_translations t ON t.article_id = f.id AND t.article_version = f.version
485	            AND t.superseded_at IS NULL) AS translated,
486	         (SELECT count(*)::text FROM foreign_sel f
487	           JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
488	            AND j.part = 'translation'
489	            AND j.state IN ('queued','running','failed_retryable')) AS queued,
490	         (SELECT count(*)::text FROM foreign_sel f
491	           JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
492	            AND j.part = 'translation' AND j.state = 'deferred_budget') AS paused,
493	         (SELECT count(*)::text FROM foreign_sel f
494	           JOIN enrichment_jobs j ON j.article_id = f.id AND j.article_version = f.version
495	            AND j.part = 'translation' AND j.state = 'dead') AS failed,
496	         (SELECT count(*)::text FROM foreign_sel f
497	           WHERE NOT EXISTS (
498	             SELECT 1 FROM enrichment_jobs j
499	              WHERE j.article_id = f.id AND j.part = 'translation'
500	           )) AS older_not_scheduled`,
501	      params,
502	    );
503	
504	    const r = res.rows[0];
505	    const baseCount = Number(r?.base_count ?? 0);
506	    const selCount = Number(r?.sel_count ?? 0);
507	    const excluded = derivedFilterActive ? Math.max(0, baseCount - selCount) : 0;
508	
509	    return {
510	      articles_matching_base_filters: baseCount,
511	      articles_in_scope: selCount,
512	      excluded_by_filter_not_enriched: excluded,
513	      summary_missing: Number(r?.summary_missing ?? 0),
514	      translation: {
515	        selection: selCount,
516	        foreign: Number(r?.foreign ?? 0),
517	        translated: Number(r?.translated ?? 0),
518	        queued: Number(r?.queued ?? 0),
519	        paused: Number(r?.paused ?? 0),
520	        failed: Number(r?.failed ?? 0),
521	        older_not_scheduled: Number(r?.older_not_scheduled ?? 0),
522	      },
523	    };
524	  } catch {
525	    return null;
526	  }
527	}
