1	export type SearchFilters = {
2	  from?: Date | undefined;
3	  to?: Date | undefined;
4	  sources?: string[] | undefined;
5	  languages?: string[] | undefined;
6	  sentiments?: string[] | undefined;
7	  topics?: string[] | undefined;
8	};
9	
10	export type FilterBuild = {
11	  clauses: string[];
12	  params: unknown[];
13	  nextIndex: number;
14	};
15	
16	/** Parse date-only YYYY-MM-DD as 00:00:00Z; `to` is exclusive. */
17	export function parseDateParam(value: string | null | undefined, edge: "from" | "to"): Date | undefined {
18	  if (!value) return undefined;
19	  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
20	    return new Date(`${value}T00:00:00.000Z`);
21	  }
22	  const d = new Date(value);
23	  if (Number.isNaN(d.getTime())) return undefined;
24	  return d;
25	}
26	
27	export function buildFilterClauses(
28	  filters: SearchFilters,
29	  startIndex: number,
30	): FilterBuild {
31	  const clauses: string[] = [];
32	  const params: unknown[] = [];
33	  let i = startIndex;
34	
35	  if (filters.from) {
36	    clauses.push(`a.published_at >= $${i}`);
37	    params.push(filters.from.toISOString());
38	    i++;
39	  }
40	  if (filters.to) {
41	    clauses.push(`a.published_at < $${i}`);
42	    params.push(filters.to.toISOString());
43	    i++;
44	  }
45	  if (filters.sources && filters.sources.length > 0) {
46	    clauses.push(`a.source = ANY($${i}::text[])`);
47	    params.push(filters.sources);
48	    i++;
49	  }
50	  if (filters.languages && filters.languages.length > 0) {
51	    clauses.push(`a.language = ANY($${i}::text[])`);
52	    params.push(filters.languages);
53	    i++;
54	  }
55	
56	  if (filters.sentiments && filters.sentiments.length > 0) {
57	    const hasNot = filters.sentiments.includes("not_enriched");
58	    const values = filters.sentiments.filter((s) => s !== "not_enriched");
59	    const parts: string[] = [];
60	    if (values.length) {
61	      parts.push(`EXISTS (
62	        SELECT 1 FROM derived_values d
63	        WHERE d.article_id = a.id AND d.field = 'sentiment' AND d.is_current
64	          AND d.value = ANY($${i}::text[])
65	      )`);
66	      params.push(values);
67	      i++;
68	    }
69	    if (hasNot) {
70	      parts.push(`NOT EXISTS (
71	        SELECT 1 FROM derived_values d
72	        WHERE d.article_id = a.id AND d.field = 'sentiment' AND d.is_current
73	      )`);
74	    }
75	    if (parts.length) clauses.push(`(${parts.join(" OR ")})`);
76	  }
77	
78	  if (filters.topics && filters.topics.length > 0) {
79	    const hasNot = filters.topics.includes("not_enriched");
80	    const values = filters.topics.filter((t) => t !== "not_enriched");
81	    const parts: string[] = [];
82	    if (values.length) {
83	      parts.push(`EXISTS (
84	        SELECT 1 FROM derived_values d
85	        WHERE d.article_id = a.id AND d.field = 'topic' AND d.is_current
86	          AND d.value = ANY($${i}::text[])
87	      )`);
88	      params.push(values);
89	      i++;
90	    }
91	    if (hasNot) {
92	      parts.push(`NOT EXISTS (
93	        SELECT 1 FROM derived_values d
94	        WHERE d.article_id = a.id AND d.field = 'topic' AND d.is_current
95	      )`);
96	    }
97	    if (parts.length) clauses.push(`(${parts.join(" OR ")})`);
98	  }
99	
100	  return { clauses, params, nextIndex: i };
101	}
102	
103	export function baseFiltersOnly(filters: SearchFilters): SearchFilters {
104	  const out: SearchFilters = {};
105	  if (filters.from) out.from = filters.from;
106	  if (filters.to) out.to = filters.to;
107	  if (filters.sources) out.sources = filters.sources;
108	  if (filters.languages) out.languages = filters.languages;
109	  return out;
110	}
