32	  const pool = getWebPool(config.db);
33	  const result = await runSearch(pool, sp);
34	  const headers = new Headers({ "Content-Type": "application/json" });
35	  if ("timing" in result && result.timing !== undefined) {
36	    headers.set("Server-Timing", `db;dur=${result.timing.toFixed(1)}`);
37	  }
38	  if (result.status === 503) {
39	    const err = (result.body as { error?: { code?: string } }).error;
40	    if (err?.code === "timeout") searchTimeouts.inc();
41	  } else if (result.status === 200 && "timing" in result && result.timing !== undefined) {
42	    const body = result.body as {
