3	export type CursorPayload = {
4	  publishedAt: string;
5	  id: string;
6	  filterHash: string;
7	};
8	
9	export function hashFilters(raw: string): string {
10	  return createHmac("sha256", "filter").update(raw).digest("hex").slice(0, 16);
11	}
12	
13	export function encodeCursor(payload: CursorPayload, secret: string): string {
14	  const body = Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
15	  const sig = createHmac("sha256", secret).update(body).digest("base64url");
16	  return `${body}.${sig}`;
17	}
18	
19	export function decodeCursor(token: string, secret: string): CursorPayload | null {
20	  const [body, sig] = token.split(".");
21	  if (!body || !sig) return null;
22	  const expected = createHmac("sha256", secret).update(body).digest("base64url");
23	  try {
24	    const a = Buffer.from(sig);
25	    const b = Buffer.from(expected);
26	    if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
27	  } catch {
28	    return null;
29	  }
30	  try {
31	    return JSON.parse(Buffer.from(body, "base64url").toString("utf8")) as CursorPayload;
32	  } catch {
33	    return null;
34	  }
